// =====================================================================
// Process machine data  (input: msg.payload = JSON จากเครื่องจักร)
// output 1 -> InfluxDB write (line protocol)
// output 2 -> Alert (ส่งต่อ Telegram / Sheets)
// =====================================================================
const d = msg.payload;
if (!d || typeof d !== "object" || !d.machine) {
    node.warn("invalid machine payload");
    return null;
}

const TEMP_WARN = 85;      // C
const VIB_TRIP = 11;       // mm/s
const VIB_PREDICT = 4.5;   // เริ่มดูแนวโน้มเมื่อเกินค่านี้
const SLOPE_PREDICT = 0.03; // mm/s ต่อ sample
const HIST = 10;           // จำนวน sample ล่าสุดที่ใช้คำนวณแนวโน้ม
const now = Date.now();
const ts = Number(d.ts) || now;

// ---------- เก็บค่าล่าสุดไว้ใช้กับ /status, Sheets, /api/status ----------
const latest = global.get("latest") || {};
latest[d.machine] = Object.assign({}, d, { received: now });
global.set("latest", latest);

// ---------- InfluxDB line protocol ----------
const esc = (v) => String(v).replace(/([,= \\])/g, "\\$1");
const str = (v) => '"' + String(v ?? "").replace(/(["\\])/g, "\\$1") + '"';
const num = (v) => (Number.isFinite(Number(v)) ? Number(v) : 0);
const int = (v) => Math.round(num(v)) + "i";

const tags = [
    "machine=" + esc(d.machine),
    "line=" + esc(d.line || "-"),
    "zone=" + esc(d.zone || "-"),
    "name=" + esc(d.name || d.machine),
];
const fields = [
    "temp=" + num(d.temp),
    "vibration=" + num(d.vibration),
    "rpm=" + num(d.rpm),
    "state_code=" + int(d.state_code),
    "count_total=" + int(d.count_total),
    "count_good=" + int(d.count_good),
    "count_reject=" + int(d.count_reject),
    "availability=" + num(d.availability),
    "performance=" + num(d.performance),
    "quality=" + num(d.quality),
    "oee=" + num(d.oee),
    "wear=" + num(d.wear),
    "state=" + str(d.state),
    "fault=" + str(d.fault),
];
const lines = ["machine," + tags.join(",") + " " + fields.join(",") + " " + ts];

// ---------- Alarm / Predictive logic ----------
const st = flow.get("alarmState") || {};
const s = st[d.machine] || { prev: null, last: {}, hist: [], lastTs: ts };
const tick = Math.max(0.5, (ts - (s.lastTs || ts)) / 1000) || 2;
s.lastTs = ts;
s.hist.push(num(d.vibration));
if (s.hist.length > HIST) s.hist.shift();

function slope(arr) {
    const n = arr.length;
    if (n < 8) return 0;
    let sx = 0, sy = 0, sxy = 0, sxx = 0;
    for (let i = 0; i < n; i++) { sx += i; sy += arr[i]; sxy += i * arr[i]; sxx += i * i; }
    return (n * sxy - sx * sy) / (n * sxx - sx * sx);
}
function cooled(type, ms) {
    const t = s.last[type] || 0;
    if (now - t < ms) return false;
    s.last[type] = now;
    return true;
}

const alerts = [];
const label = `${d.machine} (${d.name || ""})`;
const code = num(d.state_code);

if (code === 2 && s.prev !== 2) {
    const reason = { overtemp: "อุณหภูมิสูงเกิน", overvibration: "สั่นสะเทือนเกิน", jam: "ชิ้นงานติด" }[d.trip_reason] || d.trip_reason || "ไม่ทราบสาเหตุ";
    alerts.push({ level: "critical", type: "TRIP", text: `🚨 ${label} หยุดฉุกเฉิน: ${reason}\nTemp ${num(d.temp).toFixed(1)}°C | Vib ${num(d.vibration).toFixed(2)} mm/s` });
}
if (code === 1 && num(d.temp) >= TEMP_WARN && cooled("TEMP", 5 * 60 * 1000)) {
    alerts.push({ level: "warning", type: "OVERTEMP", text: `🌡️ ${label} อุณหภูมิสูง ${num(d.temp).toFixed(1)}°C (เกณฑ์เตือน ${TEMP_WARN}°C)` });
}
const sl = slope(s.hist);
if (code === 1 && num(d.vibration) >= VIB_PREDICT && sl >= SLOPE_PREDICT && cooled("PREDICT", 10 * 60 * 1000)) {
    const etaSec = Math.max(0, (VIB_TRIP - num(d.vibration)) / sl * tick);
    const eta = etaSec >= 60 ? `${(etaSec / 60).toFixed(1)} นาที` : `${Math.round(etaSec)} วินาที`;
    alerts.push({
        level: "warning", type: "PREDICT",
        text: `🔮 Predictive: ${label} ค่าสั่นกำลังไต่ขึ้น (${num(d.vibration).toFixed(2)} mm/s, +${sl.toFixed(3)}/รอบ)\nคาดว่าจะ Trip ในอีก ~${eta} แนะนำตรวจลูกปืนก่อนเครื่องพัง`,
    });
}
if (code === 1 && (s.prev === 2 || s.prev === 3)) {
    alerts.push({ level: "info", type: "RECOVER", text: `✅ ${label} กลับมาทำงานปกติแล้ว` });
    s.hist = [];
}
s.prev = code;
st[d.machine] = s;
flow.set("alarmState", st);

// event log ลง InfluxDB (ใช้ทำตาราง Alarm log ใน Grafana)
for (const a of alerts) {
    lines.push(`event,machine=${esc(d.machine)},level=${a.level},type=${a.type} message=${str(a.text.replace(/\n/g, " | "))},value=1i ${ts}`);
}

const influxMsg = {
    url: `${env.get("INFLUX_URL")}/api/v2/write?org=${encodeURIComponent(env.get("INFLUX_ORG"))}&bucket=${encodeURIComponent(env.get("INFLUX_BUCKET"))}&precision=ms`,
    method: "POST",
    headers: { Authorization: "Token " + env.get("INFLUX_TOKEN"), "Content-Type": "text/plain; charset=utf-8" },
    payload: lines.join("\n"),
};

const alertMsgs = alerts.map((a) => ({
    topic: "alert",
    payload: Object.assign({ machine: d.machine, name: d.name, ts }, a),
}));

node.status({ fill: code === 1 ? "green" : code === 2 ? "red" : "yellow", shape: "dot", text: `${d.machine} ${d.state} ${new Date().toLocaleTimeString()}` });
return [influxMsg, alertMsgs.length ? alertMsgs : null];

// =====================================================================
// Alert router  (input: msg.payload = alert จาก Process machine data)
// output 1 -> Telegram (ข้อความ + ปุ่มเปิด Google Form แจ้งซ่อม)
// output 2 -> Google Sheets (แท็บ Alarms)
// =====================================================================
const a = msg.payload;
const icon = { critical: "🔴 CRITICAL", warning: "🟠 WARNING", info: "🟢 INFO" }[a.level] || a.level;
const time = new Date(a.ts).toLocaleString("th-TH", { timeZone: "Asia/Bangkok" });

let buttons = null;
const form = env.get("FORM_PREFILL_URL") || "";
if ((a.type === "TRIP" || a.type === "PREDICT") && form && !form.includes("CHANGE_ME")) {
    buttons = [[{ text: `📝 แจ้งซ่อม ${a.machine} (Google Form)`, url: form.replace("{machine}", encodeURIComponent(a.machine)) }]];
}

const tg = {
    payload: {
        text: `<b>${icon}</b> | ${time}\n${a.text}`,
        buttons,
    },
};

const sheet = {
    payload: {
        action: "alarm",
        row: [time, a.machine, a.name || "", a.level, a.type, a.text.replace(/\n/g, " | ")],
    },
};
return [tg, sheet];

// =====================================================================
// Telegram sendMessage builder (W11)
// input: msg.payload = { text, chat_id?, buttons? }
// output -> http request (POST https://api.telegram.org/bot<TOKEN>/sendMessage)
// =====================================================================
const token = env.get("TELEGRAM_BOT_TOKEN") || "";
const chat = msg.payload.chat_id || env.get("TELEGRAM_CHAT_ID");
if (!token || token.includes("CHANGE_ME") || !chat || String(chat).includes("CHANGE_ME")) {
    node.status({ fill: "grey", shape: "ring", text: "Telegram ยังไม่ตั้งค่า token/chat_id" });
    return null;
}
const body = {
    chat_id: chat,
    text: msg.payload.text,
    parse_mode: "HTML",
    disable_web_page_preview: true,
};
if (msg.payload.buttons) body.reply_markup = { inline_keyboard: msg.payload.buttons };

node.status({ fill: "blue", shape: "dot", text: "sent " + new Date().toLocaleTimeString() });
return {
    url: `https://api.telegram.org/bot${token}/sendMessage`,
    method: "POST",
    headers: { "Content-Type": "application/json" },
    payload: body,
};

// =====================================================================
// Production log ทุก 1 นาที -> Google Sheets แท็บ Log (W10)
// อ่านค่าล่าสุดของทุกเครื่องจาก flow context
// =====================================================================
const latest = global.get("latest") || {};
const ids = Object.keys(latest).sort();
if (!ids.length) return null;

const time = new Date().toLocaleString("th-TH", { timeZone: "Asia/Bangkok" });
const rows = ids.map((id) => {
    const d = latest[id];
    return [
        time, d.machine, d.name || "", d.zone || "", d.state,
        d.temp, d.vibration, d.count_total, d.count_good, d.count_reject,
        Math.round((d.oee || 0) * 1000) / 10,
    ];
});
return { payload: { action: "log", rows } };

// =====================================================================
// Google Sheets (Apps Script Web App) builder (W10)
// input: msg.payload = { action: "log"|"alarm"|..., ... }
// output -> http request POST SHEETS_URL
// =====================================================================
const url = env.get("SHEETS_URL") || "";
if (!url || url.includes("CHANGE_ME")) {
    node.status({ fill: "grey", shape: "ring", text: "SHEETS_URL ยังไม่ตั้งค่า" });
    return null;
}
node.status({ fill: "green", shape: "dot", text: msg.payload.action + " " + new Date().toLocaleTimeString() });
return {
    url,
    method: "POST",
    headers: { "Content-Type": "application/json" },
    payload: JSON.stringify(msg.payload),
};

// =====================================================================
// GET /api/status -> JSON สถานะเครื่องทั้งหมด
// ใช้กับหน้า Factory Portal บน Azure (เข้าผ่าน DDNS + Port Forwarding, W9)
// =====================================================================
const latest = global.get("latest") || {};
const machines = Object.keys(latest).sort().map((k) => {
    const d = latest[k];
    return {
        machine: d.machine, name: d.name, zone: d.zone, state: d.state, state_code: d.state_code,
        temp: d.temp, vibration: d.vibration, oee: d.oee, count_total: d.count_total,
        online: Date.now() - d.received < 15000,
    };
});
const oee = machines.length ? machines.reduce((s, m) => s + Number(m.oee || 0), 0) / machines.length : 0;
msg.payload = { updated: new Date().toISOString(), factory_oee: Math.round(oee * 10000) / 10000, machines };
return msg;

// =====================================================================
// GET /api/cmd?machine=M3&action=fault&fault=bearing
//   action: stop | start | fault | maintenance | repair | reset_shift
//   machine: M1-M6 หรือ all
// ใช้กับ TEST-FAULT.bat, ปุ่มเดโม และทดสอบจากเบราว์เซอร์
// ถ้าตั้ง CMD_API_KEY ใน .env ต้องส่ง &key=... ด้วย (แนะนำเมื่อเปิด Port Forwarding)
// output 1 -> MQTT local | output 2 -> MQTT HiveMQ (M6) | output 3 -> http response
// =====================================================================
const q = msg.req.query || {};
const key = env.get("CMD_API_KEY") || "";
const reply = (code, body) => [null, null, { req: msg.req, res: msg.res, statusCode: code, payload: body }];

if (key && q.key !== key) return reply(403, { ok: false, error: "invalid key" });

const action = String(q.action || "").toLowerCase();
const allowed = ["stop", "start", "fault", "maintenance", "repair", "reset_shift"];
if (!allowed.includes(action)) return reply(400, { ok: false, error: "action must be one of " + allowed.join(", ") });

const target = String(q.machine || "").toUpperCase();
if (!/^(M\d+|ALL)$/.test(target)) return reply(400, { ok: false, error: "machine must be M1..M6 or all" });

const body = { action, by: "api" };
if (action === "fault") body.fault = String(q.fault || "bearing").toLowerCase();

const prefix = env.get("HIVEMQ_PREFIX") || "smf";
const local = [], hive = [];
if (target === "ALL") {
    local.push({ topic: "factory/cmd/all", payload: JSON.stringify(body) });
    hive.push({ topic: `${prefix}/factory/cmd/M6`, payload: JSON.stringify(body) });
} else if (target === "M6") {
    hive.push({ topic: `${prefix}/factory/cmd/M6`, payload: JSON.stringify(body) });
} else {
    local.push({ topic: `factory/cmd/${target}`, payload: JSON.stringify(body) });
}
node.status({ fill: "blue", shape: "dot", text: `${target} ${action} ${body.fault || ""}` });
return [local, hive, { req: msg.req, res: msg.res, statusCode: 200, payload: { ok: true, machine: target, ...body } }];

// =====================================================================
// Telegram getUpdates (polling ทุก 3 วินาที) - รับคำสั่งจากแชท
// =====================================================================
const token = env.get("TELEGRAM_BOT_TOKEN") || "";
if (!token || token.includes("CHANGE_ME")) return null;

// กันยิงซ้อนถ้ารอบก่อนยังไม่ตอบกลับ (หมดเวลา 15 วินาทีถือว่าค้าง)
const busy = flow.get("tgBusy") || 0;
if (Date.now() - busy < 15000) return null;
flow.set("tgBusy", Date.now());

const offset = flow.get("tgOffset") || 0;
return {
    url: `https://api.telegram.org/bot${token}/getUpdates?timeout=0&offset=${offset}&allowed_updates=%5B%22message%22%5D`,
    method: "GET",
};

// =====================================================================
// Telegram command parser
// output 1 -> MQTT คำสั่งเครื่อง M1-M5 (local Mosquitto)
// output 2 -> MQTT คำสั่งเครื่อง M6 (Wokwi ESP32 ผ่าน HiveMQ)
// output 3 -> ตอบกลับ Telegram
// output 4 -> เรียก n8n (AI report / ถาม AI)
// =====================================================================
flow.set("tgBusy", 0);
const res = msg.payload;
if (!res || !res.ok || !Array.isArray(res.result)) return null;

const allowed = (env.get("TELEGRAM_ALLOWED") || env.get("TELEGRAM_CHAT_ID") || "")
    .split(",").map((x) => x.trim()).filter(Boolean);
const latest = global.get("latest") || {};
const prefix = env.get("HIVEMQ_PREFIX") || "smf";
const n8n = env.get("N8N_URL") || "http://n8n:5678";

const out1 = [], out2 = [], out3 = [], out4 = [];
const reply = (chat_id, text) => out3.push({ payload: { chat_id, text } });
const pct = (v) => (Number(v || 0) * 100).toFixed(1) + "%";
const dot = (c) => ["⚪", "🟢", "🔴", "🟠"][c] || "⚪";

function sendCmd(id, body) {
    const m = { topic: null, payload: JSON.stringify(body) };
    if (id === "M6") { m.topic = `${prefix}/factory/cmd/M6`; out2.push(m); }
    else { m.topic = `factory/cmd/${id}`; out1.push(m); }
}
function targets(arg) {
    if (!arg) return [];
    const a = arg.toUpperCase();
    if (a === "ALL") return Object.keys(latest).sort();
    return /^M\d+$/.test(a) ? [a] : [];
}
function statusLine(d) {
    return `${dot(d.state_code)} <b>${d.machine}</b> ${d.name || ""}\n   ${d.state} | ${Number(d.temp).toFixed(1)}°C | ${Number(d.vibration).toFixed(2)} mm/s | OEE ${pct(d.oee)}`;
}

const HELP = [
    "<b>🏭 Smart Factory Bot</b>",
    "/status – สถานะทุกเครื่อง",
    "/status M3 – รายละเอียดเครื่อง",
    "/oee – สรุป OEE ทั้งโรงงาน",
    "/stop M3 | /run M3 – หยุด/เดินเครื่อง (ใช้ all ได้)",
    "/fault M3 bearing|overheat|jam – จำลองเครื่องเสีย",
    "/maint M3 – เข้าสู่โหมดซ่อมบำรุง",
    "/repair M3 – ซ่อมเสร็จ เดินเครื่องต่อ",
    "/report – ให้ AI สรุปรายงานกะ",
    "/ask คำถาม – ถาม AI จากข้อมูลจริง",
].join("\n");

let maxId = flow.get("tgOffset") || 0;
for (const u of res.result) {
    maxId = Math.max(maxId, u.update_id + 1);
    const m = u.message;
    if (!m || !m.text) continue;
    const chat = String(m.chat.id);
    if (allowed.length && !allowed.includes(chat)) {
        reply(chat, `⛔ chat นี้ไม่มีสิทธิ์สั่งงาน (chat_id: ${chat})`);
        continue;
    }
    const [rawCmd, ...rest] = m.text.trim().split(/\s+/);
    const cmd = rawCmd.split("@")[0].toLowerCase();
    const arg = rest[0];
    const ids = targets(arg);

    switch (cmd) {
        case "/start":
        case "/help":
            reply(chat, HELP);
            break;
        case "/status": {
            if (ids.length === 1 && latest[ids[0]]) {
                const d = latest[ids[0]];
                reply(chat, [
                    statusLine(d),
                    `   RPM ${d.rpm} | Wear ${pct(d.wear)} | Fault: ${d.fault}`,
                    `   ผลิต ${d.count_total} (ดี ${d.count_good} / เสีย ${d.count_reject})`,
                    `   A ${pct(d.availability)} × P ${pct(d.performance)} × Q ${pct(d.quality)} = OEE ${pct(d.oee)}`,
                ].join("\n"));
            } else {
                const lines = Object.keys(latest).sort().map((k) => statusLine(latest[k]));
                reply(chat, lines.length ? "<b>📊 สถานะเครื่องจักร</b>\n" + lines.join("\n") : "ยังไม่มีข้อมูลจากเครื่องจักร");
            }
            break;
        }
        case "/oee": {
            const ds = Object.values(latest);
            if (!ds.length) { reply(chat, "ยังไม่มีข้อมูล"); break; }
            const avg = ds.reduce((s, d) => s + Number(d.oee || 0), 0) / ds.length;
            const total = ds.reduce((s, d) => s + Number(d.count_total || 0), 0);
            const worst = ds.slice().sort((a, b) => a.oee - b.oee)[0];
            reply(chat, `<b>📈 OEE โรงงาน ${pct(avg)}</b>\nผลิตรวม ${total} ชิ้น\nต่ำสุด: ${worst.machine} ${pct(worst.oee)}\n(มาตรฐานระดับโลก ≥ 85%)`);
            break;
        }
        case "/stop":
        case "/run":
        case "/maint":
        case "/repair": {
            if (!ids.length) { reply(chat, `ระบุเครื่องด้วย เช่น ${cmd} M3`); break; }
            const action = { "/stop": "stop", "/run": "start", "/maint": "maintenance", "/repair": "repair" }[cmd];
            ids.forEach((id) => sendCmd(id, { action, by: m.from.first_name || "telegram" }));
            reply(chat, `📨 ส่งคำสั่ง <b>${action}</b> ไปที่ ${ids.join(", ")} แล้ว`);
            break;
        }
        case "/fault": {
            if (!ids.length) { reply(chat, "เช่น /fault M3 bearing"); break; }
            const f = (rest[1] || "bearing").toLowerCase();
            ids.forEach((id) => sendCmd(id, { action: "fault", fault: f }));
            reply(chat, `🧪 จำลองความเสียหาย <b>${f}</b> ที่ ${ids.join(", ")}`);
            break;
        }
        case "/report":
            out4.push({ url: `${n8n}/webhook/factory-report`, method: "POST", headers: { "Content-Type": "application/json" }, payload: { chat_id: chat } });
            reply(chat, "⏳ กำลังให้ AI สรุปรายงานกะ...");
            break;
        case "/ask": {
            const q = rest.join(" ").trim();
            if (!q) { reply(chat, "เช่น /ask เครื่องไหนน่าห่วงที่สุดตอนนี้"); break; }
            out4.push({ url: `${n8n}/webhook/factory-ask`, method: "POST", headers: { "Content-Type": "application/json" }, payload: { chat_id: chat, question: q } });
            reply(chat, "🤖 กำลังวิเคราะห์ข้อมูล...");
            break;
        }
        default:
            reply(chat, "ไม่รู้จักคำสั่งนี้ พิมพ์ /help");
    }
}
flow.set("tgOffset", maxId);
return [out1, out2, out3, out4];

// =====================================================================
// Telegram sendMessage builder (W11)
// input: msg.payload = { text, chat_id?, buttons? }
// output -> http request (POST https://api.telegram.org/bot<TOKEN>/sendMessage)
// =====================================================================
const token = env.get("TELEGRAM_BOT_TOKEN") || "";
const chat = msg.payload.chat_id || env.get("TELEGRAM_CHAT_ID");
if (!token || token.includes("CHANGE_ME") || !chat || String(chat).includes("CHANGE_ME")) {
    node.status({ fill: "grey", shape: "ring", text: "Telegram ยังไม่ตั้งค่า token/chat_id" });
    return null;
}
const body = {
    chat_id: chat,
    text: msg.payload.text,
    parse_mode: "HTML",
    disable_web_page_preview: true,
};
if (msg.payload.buttons) body.reply_markup = { inline_keyboard: msg.payload.buttons };

node.status({ fill: "blue", shape: "dot", text: "sent " + new Date().toLocaleTimeString() });
return {
    url: `https://api.telegram.org/bot${token}/sendMessage`,
    method: "POST",
    headers: { "Content-Type": "application/json" },
    payload: body,
};

// =====================================================================
// ดึงใบแจ้งซ่อมใหม่จาก Google Form (ผ่าน Apps Script) ทุก 20 วินาที
// =====================================================================
const url = env.get("SHEETS_URL") || "";
if (!url || url.includes("CHANGE_ME")) return null;
const last = flow.get("repairLastRow");
// ครั้งแรกหลังเปิดระบบ: ขอแค่เลขแถวล่าสุด ไม่ย้อนทำใบเก่า
const after = last === undefined ? -1 : last;
return { url: `${url}?action=repairs&after=${after}`, method: "GET" };

// =====================================================================
// ปิดลูปงานซ่อม: Google Form -> Node-RED -> สั่งเครื่อง + แจ้ง Telegram
// input : { lastRow, repairs: [{row, timestamp, machine, technician, cause, action, result, photo}] }
// output 1 -> MQTT local (M1-M5) | output 2 -> MQTT HiveMQ (M6)
// output 3 -> Telegram          | output 4 -> InfluxDB event
// =====================================================================
const r = msg.payload;
if (!r || typeof r !== "object" || r.lastRow === undefined) {
    node.status({ fill: "red", shape: "ring", text: "Apps Script ตอบกลับไม่ถูกต้อง" });
    return null;
}
const first = flow.get("repairLastRow") === undefined;
flow.set("repairLastRow", r.lastRow);
if (first) {
    node.status({ fill: "green", shape: "dot", text: `พร้อมรับใบซ่อม (แถวล่าสุด ${r.lastRow})` });
    return null;
}

const prefix = env.get("HIVEMQ_PREFIX") || "smf";
const out1 = [], out2 = [], out3 = [], out4 = [];
const str = (v) => '"' + String(v ?? "").replace(/(["\\])/g, "\\$1") + '"';

for (const j of r.repairs || []) {
    const id = String(j.machine || "").toUpperCase().match(/M\d+/);
    if (!id) continue;
    const mid = id[0];
    const done = /เสร็จ|done|complete|ok/i.test(j.result || "");
    const action = done ? "repair" : "maintenance";
    const cmd = { payload: JSON.stringify({ action, by: j.technician || "form" }) };
    if (mid === "M6") { cmd.topic = `${prefix}/factory/cmd/M6`; out2.push(cmd); }
    else { cmd.topic = `factory/cmd/${mid}`; out1.push(cmd); }

    const text = done
        ? `🔧 <b>${mid} ซ่อมเสร็จ</b> โดย ${j.technician || "-"}\nสาเหตุ: ${j.cause || "-"}\nการแก้ไข: ${j.action || "-"}\n➡️ ระบบสั่งเดินเครื่องอัตโนมัติแล้ว`
        : `🛠️ <b>${mid} เข้าโหมดซ่อมบำรุง</b> (${j.result || "รอดำเนินการ"}) โดย ${j.technician || "-"}\nสาเหตุ: ${j.cause || "-"}`;
    const photo = j.photo ? `\n📷 <a href="${j.photo}">รูปประกอบ (Google Drive)</a>` : "";
    out3.push({ payload: { text: text + photo } });

    out4.push({
        url: `${env.get("INFLUX_URL")}/api/v2/write?org=${encodeURIComponent(env.get("INFLUX_ORG"))}&bucket=${encodeURIComponent(env.get("INFLUX_BUCKET"))}&precision=ms`,
        method: "POST",
        headers: { Authorization: "Token " + env.get("INFLUX_TOKEN"), "Content-Type": "text/plain; charset=utf-8" },
        payload: `event,machine=${mid},level=info,type=${done ? "REPAIRED" : "MAINTENANCE"} message=${str(`${j.technician || ""}: ${j.cause || ""} -> ${j.action || ""}`)},value=1i ${Date.now()}`,
    });
}
node.status({ fill: "green", shape: "dot", text: `แถวล่าสุด ${r.lastRow} | ใบใหม่ ${(r.repairs || []).length}` });
return [out1, out2, out3, out4];
